import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`earnings-model-refresh`,heroTitle:`Refresh your earnings model in minutes`,heroSubtitle:`Perplexity Computer reviews the latest earnings materials, updates assumptions, and turns a stale model into a refreshed investment view.`,inputUrlCta:`Refresh this model`,inputUrlPlaceholder:`ticker, company site, or earnings URL`,inputUrlPrefill:`Go to {url} and refresh the earnings model for this company. 1) Identify the company, ticker, latest quarter, reporting date, guidance, and key business drivers. 2) Pull the latest reported revenue, margins, segment trends, cash flow, balance sheet items, and management commentary. 3) Compare results against prior assumptions and consensus where available. 4) Update the model drivers, scenario assumptions, valuation sensitivities, and key risks. 5) Deliver a refreshed earnings model summary with assumption changes, upside/downside drivers, and investor takeaways.`,heroOverlaySteps:[`Pulling latest earnings results, guidance, and management commentary`,`Comparing reported drivers against prior assumptions`,`Updating scenarios, valuation sensitivities, and key risks`,`Refreshed model summary and investor takeaways ready to review`],generatingSteps:[`Looking up {url} to identify the company, quarter, guidance, and earnings materials`,`Designing an agent to compare reported results with prior assumptions`,`Configuring updated drivers, scenarios, valuation sensitivities, and risk notes`,`Setting up the refreshed model summary and investor takeaway report`],featureSectionTitle:`From earnings release to refreshed model`,featureCardTitles:[`Connects to your investing stack`,`Outputs you can use`],featureCardDescriptions:[`Computer breaks the refresh into earnings collection, variance analysis, assumption updates, and investment summary writing.`,`Company filings, earnings decks, spreadsheets, Drive, Notion, and Slack can feed one organized model refresh workflow.`,`Updated assumptions. Scenario drivers. Sensitivity notes. Risk watchlist. Investor takeaways. Computer gives you a refreshed view ready for discussion.`],capabilitySectionTitle:`Your earnings analyst, on autopilot`,capabilitySectionSubtitle:`Enter a ticker or earnings URL and get a refreshed model summary.`,capabilityCards:[{title:`Earnings Pull`,description:`Computer can collect reported revenue, margins, segment trends, cash flow, guidance, and management commentary.`},{title:`Assumption Variance`,description:`Computer can compare new results against prior model assumptions and identify where drivers need to change.`},{title:`Scenario Refresh`,description:`Computer can update bear, base, and bull assumptions, valuation sensitivities, and key risk factors.`},{title:`Connect Your Tools`,description:`Computer can organize earnings decks, filings, spreadsheets, Drive folders, Notion notes, and Slack updates.`},{title:`Remember Your Model`,description:`Computer can remember your preferred drivers, valuation framework, sensitivity ranges, and investment memo style.`},{title:`Earnings Alerts`,description:`Computer can watch for new releases, guidance changes, and material driver shifts that require another model refresh.`}]});export{t as default};
